// Client-side cosine similarity against the bundled COSMIC SBS reference
// catalog (web/public/cosmic-sbs.json, generated by
// scripts/make_cosmic_catalog.py). The API is untouched: similarity is
// computed in the browser from the returned signature matrix.

import { CONTEXTS_96 } from "./csv.js";

export async function fetchCosmicCatalog() {
  const response = await fetch("/cosmic-sbs.json");
  if (!response.ok) throw new Error("COSMIC catalog unavailable");
  return response.json();
}

function cosine(a, b) {
  let dot = 0;
  let normA = 0;
  let normB = 0;
  for (let i = 0; i < a.length; i += 1) {
    dot += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }
  const denominator = Math.sqrt(normA) * Math.sqrt(normB);
  return denominator > 0 ? dot / denominator : 0;
}

// Returns, per signature, the catalog entries sorted by similarity
// (top `topN`), or null when the result is not a 96-context profile that
// can be aligned to the catalog's canonical order.
export function nearestCosmic(catalog, signatures, mutationTypes, topN = 3) {
  if (!catalog || signatures.length !== 96) return null;

  // Map canonical context order -> row index in the result.
  let order;
  if (mutationTypes && mutationTypes.length === 96) {
    const rowByContext = new Map(mutationTypes.map((context, index) => [context, index]));
    order = CONTEXTS_96.map((context) => rowByContext.get(context));
    if (order.some((index) => index === undefined)) return null;
  } else if (!mutationTypes) {
    // Unlabeled 96-row matrix: assume canonical order.
    order = CONTEXTS_96.map((_, index) => index);
  } else {
    return null;
  }

  const rank = signatures[0]?.length ?? 0;
  const entries = Object.entries(catalog.signatures);
  return Array.from({ length: rank }, (_, k) => {
    const profile = order.map((rowIndex) => signatures[rowIndex][k]);
    return entries
      .map(([name, reference]) => ({ name, similarity: cosine(profile, reference) }))
      .sort((a, b) => b.similarity - a.similarity)
      .slice(0, topN);
  });
}
